window.FA_I18N = FA_I18N;
function apply(lang){
  var d = FA_I18N[lang] || {}, en = FA_I18N.en || {};
  var nodes = document.querySelectorAll('[data-vai-i18n]');
  for (var i=0;i<nodes.length;i++){
    var el = nodes[i], k = el.getAttribute('data-vai-i18n');
    if (!el.getAttribute('data-i18n-orig')) el.setAttribute('data-i18n-orig', el.textContent);
    var v = d[k] || en[k];
    if (v) { el.textContent = v; }
    else if ((el.textContent||'').trim() === k) { el.textContent = el.getAttribute('data-i18n-orig'); }
  }
}
window.faI18nApply = apply;
function curLang(){ try{ return localStorage.getItem("chitti_vaani_lang")||"hi"; }catch(e){ return "hi"; } }
function guard(){
  var nodes = document.querySelectorAll('[data-vai-i18n]'); var lang = curLang();
  for (var i=0;i<nodes.length;i++){
    var el = nodes[i], k = el.getAttribute('data-vai-i18n');
    if ((el.textContent||'').trim() === k){
      var v = (FA_I18N[lang]||{})[k] || (FA_I18N.en||{})[k] || el.getAttribute('data-i18n-orig') || '';
      if (v) el.textContent = v;
    }
  }
}
window.faI18nGuard = guard;
function boot(){ var l = curLang(); apply(l); setTimeout(function(){ apply(l); guard(); }, 250); setTimeout(guard, 900); }
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot();
window.addEventListener('chitti:langchange', function(e){ var l=(e&&e.detail&&e.detail.lang)||curLang(); apply(l); setTimeout(guard,120); });
